#include "sblr_read_stream_runtime.hpp"
#include "core/hash/hash_digest.hpp"
#include <algorithm>
namespace scratchbird::engine::sblr{namespace{bool nz(const auto&a){return std::any_of(a.begin(),a.end(),[](auto b){return b;});}void p16(auto&o,uint16_t v){o.push_back(v);o.push_back(v>>8);}void p32(auto&o,uint32_t v){for(int i=0;i<4;i++)o.push_back(v>>(8*i));}void p64(auto&o,uint64_t v){for(int i=0;i<8;i++)o.push_back(v>>(8*i));}uint16_t u16(const uint8_t*p){return p[0]|p[1]<<8;}uint32_t u32(const uint8_t*p){uint32_t v=0;for(int i=3;i>=0;i--)v=v*256+p[i];return v;}uint64_t u64(const uint8_t*p){uint64_t v=0;for(int i=7;i>=0;i--)v=v*256+p[i];return v;}void put(auto&o,const auto&a){o.insert(o.end(),a.begin(),a.end());}void get(const uint8_t*p,auto&a){std::copy(p,p+a.size(),a.begin());}bool head(const uint8_t*b,size_t n,const char*m,size_t z){return n==z&&std::equal(m,m+4,b)&&b[4]==1&&!b[5]&&u16(b+6)==z&&u32(b+8)==z&&!u32(b+12);}auto hash(const char*d,std::vector<uint8_t>b,bool neutral=false){if(neutral)b[3]=0;std::vector<uint8_t>m(d,d+std::char_traits<char>::length(d));m.insert(m.end(),b.begin(),b.end());return scratchbird::core::hash::ComputeSha256Digest(m).digest;}}
std::vector<uint8_t>EncodeSblrReadStreamRequestV1(const SblrReadStreamRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.stream_occurrence)return{};std::vector<uint8_t>o{'R','S','Q','R'};p16(o,1);p16(o,64);p32(o,64);p32(o,0);put(o,v.receipt);p64(o,v.occurrence);p32(o,v.stream_occurrence);o.insert(o.end(),20,0);return o;}bool DecodeSblrReadStreamRequestV1(const uint8_t*b,size_t n,SblrReadStreamRequestV1*out,std::string*d){if(!out||!head(b,n,"RSQR",64)){if(d)*d="RSQR invalid";return false;}SblrReadStreamRequestV1 v;get(b+16,v.receipt);v.occurrence=u64(b+32);v.stream_occurrence=u32(b+40);if(std::any_of(b+44,b+64,[](auto x){return x;})||EncodeSblrReadStreamRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrReadStreamDescriptorV1(const SblrReadStreamDescriptorV1&v,bool op){if(!nz(v.descriptor)||!v.descriptor_generation||!nz(v.relation)||!v.relation_generation||!nz(v.schema)||!v.schema_generation||!nz(v.mga)||!v.mga_generation||!nz(v.security)||!v.security_generation||!nz(v.row_shape)||!v.row_shape_generation||!nz(v.policy)||!v.policy_generation||(v.mode!=1&&v.mode!=2)||v.redaction>1||!v.maximum_rows||v.maximum_rows>65535||!v.maximum_bytes||v.maximum_bytes>16777216||!v.availability_generation)return{};std::vector<uint8_t>o{'R','S',static_cast<uint8_t>(op?'O':'D'),static_cast<uint8_t>(op?'P':'D')};if(!op)o={'R','S','D','D'};p16(o,1);p16(o,240);p32(o,240);p32(o,0);put(o,v.descriptor);p64(o,v.descriptor_generation);put(o,v.relation);p64(o,v.relation_generation);put(o,v.schema);p64(o,v.schema_generation);put(o,v.mga);p64(o,v.mga_generation);put(o,v.security);p64(o,v.security_generation);put(o,v.row_shape);p64(o,v.row_shape_generation);put(o,v.policy);p64(o,v.policy_generation);o.push_back(v.mode);o.push_back(v.redaction);o.insert(o.end(),6,0);p32(o,v.maximum_rows);p32(o,v.maximum_bytes);auto e=hash("ScratchBird.SblrReadStreamDescriptor.V1",std::vector<uint8_t>(o.begin()+16,o.end()));if(nz(v.evidence)&&v.evidence!=e)return{};put(o,e);p64(o,v.availability_generation);return o;}
bool DecodeSblrReadStreamDescriptorV1(const uint8_t*b,size_t n,SblrReadStreamDescriptorV1*out,std::string*d,bool op){if(!out||!head(b,n,op?"RSOP":"RSDD",240)){if(d)*d="stream descriptor invalid";return false;}SblrReadStreamDescriptorV1 v;get(b+16,v.descriptor);v.descriptor_generation=u64(b+32);get(b+40,v.relation);v.relation_generation=u64(b+56);get(b+64,v.schema);v.schema_generation=u64(b+80);get(b+88,v.mga);v.mga_generation=u64(b+104);get(b+112,v.security);v.security_generation=u64(b+128);get(b+136,v.row_shape);v.row_shape_generation=u64(b+152);get(b+160,v.policy);v.policy_generation=u64(b+176);v.mode=b[184];v.redaction=b[185];v.maximum_rows=u32(b+192);v.maximum_bytes=u32(b+196);get(b+200,v.evidence);v.availability_generation=u64(b+232);if(std::any_of(b+186,b+192,[](auto x){return x;})||EncodeSblrReadStreamDescriptorV1(v,op).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrReadStreamHandleV1(const SblrReadStreamHandleV1&v){if(!nz(v.descriptor)||!v.descriptor_generation||!nz(v.stream)||!v.stream_generation||!nz(v.relation)||!nz(v.row_shape)||v.state!=1||!nz(v.continuation)||!v.availability_generation)return{};std::vector<uint8_t>o{'R','S','H','D'};p16(o,1);p16(o,176);p32(o,176);p32(o,0);put(o,v.descriptor);p64(o,v.descriptor_generation);put(o,v.stream);p64(o,v.stream_generation);put(o,v.relation);put(o,v.row_shape);o.push_back(v.state);o.insert(o.end(),7,0);put(o,v.continuation);p64(o,v.availability_generation);auto e=hash("ScratchBird.SblrReadStreamHandle.V1",o);if(nz(v.evidence)&&v.evidence!=e)return{};put(o,e);return o;}bool DecodeSblrReadStreamHandleV1(const uint8_t*b,size_t n,SblrReadStreamHandleV1*out,std::string*d){if(!out||!head(b,n,"RSHD",176)){if(d)*d="RSHD invalid";return false;}SblrReadStreamHandleV1 v;get(b+16,v.descriptor);v.descriptor_generation=u64(b+32);get(b+40,v.stream);v.stream_generation=u64(b+56);get(b+64,v.relation);get(b+80,v.row_shape);v.state=b[96];get(b+104,v.continuation);v.availability_generation=u64(b+136);get(b+144,v.evidence);if(std::any_of(b+97,b+104,[](auto x){return x;})||EncodeSblrReadStreamHandleV1(v).empty())return false;*out=v;return true;}}
